const data = $input.first().json.body || $input.first().json;
const required = ['first_name','last_name','email','phone',
  'date_of_birth','ssn_last4','street','city','state','zip',
  'plan_tier','consent_given','disclosure_acknowledged',
  'croa_contract_signed','credit_data_source'];
const missing = required.filter(k =>
  data[k] === undefined || data[k] === null || data[k] === '');
const compliant = data.consent_given === true
  && data.disclosure_acknowledged === true
  && data.croa_contract_signed === true;
return [{ json: { ...data,
  _missing: missing,
  _valid: missing.length === 0,
  _compliant: compliant } }];
